const items = $input.all();
const results = [];
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

for (const item of items) {
  const payload = item.json.body || item.json;
  const data = payload.data || payload;

  const rawTo = String(payload.to || data.member_id || data.phone || '').trim();
  const explicitPhone = String(data.phone || data.member_phone || '').trim();
  const isUuid = uuidPattern.test(rawTo);
  const hasExplicitValidPhone = !uuidPattern.test(explicitPhone) && explicitPhone.replace(/[^0-9]/g, '').length >= 10;

  const memberId = isUuid ? rawTo : (data.member_id || '');
  const needsLookup = isUuid && !hasExplicitValidPhone;
  const initialPhone = hasExplicitValidPhone ? explicitPhone : (!isUuid ? rawTo : '');

  results.push({
    json: {
      rawPayload: payload,
      data,
      memberId,
      needsLookup,
      phone: initialPhone,
      rawRecipient: rawTo,
      tenantId: payload.tenantId || payload.tenant_id || 'default-tenant',
      eventId: payload.eventId || payload.event_id || `evt_${Date.now()}`,
      correlationId: payload.correlationId || payload.correlation_id || `corr_${Date.now()}`,
      template: payload.template || 'booking-confirmation'
    }
  });
}

return results;

const items = $input.all();
const results = [];
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

for (const item of items) {
  const d = item.json;
  // Check if member lookup was performed
  const apiRes = d.data || d;
  const fetchedPhone = apiRes.phone || apiRes.mobile || (apiRes.member && apiRes.member.phone) || '';

  const candidatePhone = String(fetchedPhone || d.phone || '').trim();
  const cleanDigits = candidatePhone.replace(/[^0-9]/g, '');
  const isUuid = uuidPattern.test(candidatePhone);
  const isValidPhone = !isUuid && cleanDigits.length >= 10 && cleanDigits.length <= 15;
  const resolvedPhone = cleanDigits.length >= 10 ? (candidatePhone.startsWith('+') ? candidatePhone.replace(/[^0-9+]/g, '') : `+${cleanDigits}`) : '';
  const memberName = apiRes.full_name || apiRes.name || d.data?.member_name || 'Valued Member';

  results.push({
    json: {
      ...d,
      phone: resolvedPhone,
      resolvedPhone,
      memberName,
      isValidPhone
    }
  });
}

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  const d = item.json;
  const payload = d.rawPayload || d;
  const data = d.data || payload.data || {};

  const eventType = payload.eventType || payload.event_type || payload.template || 'booking.confirmed';
  const memberName = d.memberName || data.member_name || data.memberName || 'Valued Member';
  const className = data.class_name || data.className || 'Studio Class';
  const date = data.date || data.sessionDate || new Date().toISOString().split('T')[0];
  const time = data.time || data.startTime || '10:00 AM';
  const trainerName = data.trainer_name || data.instructor || 'Lead Instructor';
  const bookingId = data.booking_id || data.id || payload.subjectRef || `bk_${Date.now()}`;
  const queuePosition = data.queue_position || data.queuePosition || 1;
  const reason = data.reason || 'Requested by member';

  let templateName = 'booking-confirmation';
  const templateVars = {
    member_name: memberName,
    class_name: className,
    date,
    time,
    trainer_name: trainerName
  };

  if (eventType.includes('waitlist') || payload.template === 'waitlist-confirmation') {
    templateName = 'waitlist-confirmation';
    templateVars.queue_position = queuePosition;
  } else if (eventType.includes('promoted') || payload.template === 'booking-promoted' || payload.template === 'seat-promotion-confirmation') {
    templateName = 'seat-promotion-confirmation';
  } else if (eventType.includes('cancelled') || payload.template === 'booking-cancellation') {
    templateName = 'booking-cancellation';
    templateVars.reason = reason;
  }

  results.push({
    json: {
      to: d.phone,
      phone: d.phone,
      template: templateName,
      template_name: templateName,
      tenantId: d.tenantId,
      eventId: d.eventId,
      correlationId: d.correlationId,
      idempotencyKey: `booking_${bookingId}_${templateName}`,
      isDirectDelivery: true,
      source: 'domain_workflow',
      workflow_name: 'booking-confirmation',
      data: templateVars
    }
  });
}

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  const d = item.json;
  results.push({
    json: {
      alertType: 'notification_failure',
      severity: 'high',
      workflow_name: 'booking-confirmation',
      eventId: d.eventId,
      recipient: d.rawRecipient || d.memberId || 'unknown',
      template: d.template || 'booking-confirmation',
      error_code: 'RECIPIENT_PHONE_UNRESOLVABLE',
      error_message: `Recipient member ID '${d.memberId}' could not be resolved to a valid phone number. API lookup failed or member phone missing.`,
      tenantId: d.tenantId,
      correlationId: d.correlationId,
      timestamp: new Date().toISOString()
    }
  });
}

return results;

